using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using Extensions.Pack;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("AsyncAwait")]
    [TestClass]
    public class RJIT_CR_AA_C_00004 : MsTestBase   
    {
        /*
         * Code Rule RJIT_CR_AA_00004 promotes using IAsyncEnumerable for asynchronous method return types, highlighting the benefits in performance, readability, and resource utilization.
         */
        [TestMethod]
        public void Use_IAsyncEnumerable_Instead_Of_IEnumerable_Of_Task()
        {
            string pattern = "IEnumerable<Task<([^>]+)>>";
            string replacement = "IAsyncEnumerable<$1>";
            var ienumerableReturnTypes = (from @class in Classes
                                         from @method in @class.Methods
                                         where method.ReturnParameter.Contains("IEnumerable<Task")
                                         select new
                                         {
                                             Error = $@"
Never use IEnumerable as return type for async methods.
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Class:  {@class.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method: {method.MethodValue.Split(Environment.NewLine)[0]}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample: {Regex.Replace(method.MethodValue.Split(Environment.NewLine)[0], pattern, replacement)}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                         }).ToImmutableList();

            Assert.IsTrue(ienumerableReturnTypes.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_AA_00004

Never use IEnumerable as return type for async methods. Findings: '{ienumerableReturnTypes.Count}': {Environment.NewLine}{ienumerableReturnTypes.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
